import{_ as a,c as t,o,a2 as i}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"Milton Plumb","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/Milton-Plumb.md","filePath":"entries/people/Milton-Plumb.md"}'),r={name:"entries/people/Milton-Plumb.md"};function s(n,e,l,c,u,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="milton-plumb" tabindex="-1">Milton Plumb <a class="header-anchor" href="#milton-plumb" aria-label="Permalink to &quot;Milton Plumb&quot;">​</a></h1><hr><p><strong>OCCUPATION</strong>: Podcast Host, Media Personality<br><strong>KNOWN FOR</strong>: SnarkCast host<br><strong>SPECIALTY</strong>: Satirical cryptocurrency and conspiracy commentary</p><hr><p><strong>Milton Plumb</strong> is an American podcast host and media personality. He is best known as the host of <em>SnarkCast</em>, a satirical podcast covering cryptocurrency markets, conspiracy theories, and government-corporate collusion.</p><p><strong>At a glance</strong></p><ul><li>Host of <em>SnarkCast</em> satirical podcast</li><li>Specializes in cryptocurrency market commentary and conspiracy theories</li><li>Known for measured, deadpan delivery as counterpoint to theatrical guests</li><li>Serves as audience surrogate, questioning guest theories with conventional interpretations</li><li>Labeled <a href="./../subjects/G-BOY">G*BOY</a> a &quot;terrorist&quot; and warned of <a href="./../organizations/The-Bloc">The Bloc</a>&#39;s blockchain activities</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Plumb serves as the primary host of <em>SnarkCast</em>, where he moderates discussions about cryptocurrency markets, government conspiracies, and alleged corporate misconduct. His presentation style features measured, thoughtful delivery that provides contrast to the more theatrical performances of his guests.</p><p>As host, Plumb typically offers conventional interpretations of events before guests challenge or dismiss them, functioning as an audience surrogate who expresses familiarity with theories while maintaining skeptical distance. This dynamic creates setup for more elaborate conspiracy explanations.</p><h2 id="snarkcast-career" tabindex="-1">SnarkCast Career <a class="header-anchor" href="#snarkcast-career" aria-label="Permalink to &quot;SnarkCast Career&quot;">​</a></h2><h3 id="format-and-style" tabindex="-1">Format and Style <a class="header-anchor" href="#format-and-style" aria-label="Permalink to &quot;Format and Style&quot;">​</a></h3><p>Plumb&#39;s hosting approach combines deadpan delivery with satirical edge, creating a podcast format that mocks financial media culture while advancing substantive discussions about cryptocurrency legitimacy and government oversight. His studio reportedly features vintage audio equipment and retro aesthetic elements consistent with 1990s and early 2000s podcast culture.</p><p>The show maintains an episodic structure with recurring segments and guest appearances. Episode teasers feature dramatic phrasing, such as &quot;Next week on SnarkCast, will you choose rich or will rich choose you?&quot;</p><h3 id="notable-episodes" tabindex="-1">Notable Episodes <a class="header-anchor" href="#notable-episodes" aria-label="Permalink to &quot;Notable Episodes&quot;">​</a></h3><h4 id="conspirazorg-episode-november-2025" tabindex="-1">Conspirazorg Episode (November 2025) <a class="header-anchor" href="#conspirazorg-episode-november-2025" aria-label="Permalink to &quot;Conspirazorg Episode (November 2025)&quot;">​</a></h4><p>Plumb hosted conspiracy theorist <a href="./Conspirazorg">Conspirazorg</a> for a discussion of <a href="./../organizations/Miter-Corporation">Miter Corporation</a> operations. Plumb initially suggested facility activities might be &quot;just putting out a bunch of random experiments, whatever comes to mind.&quot;</p><p>Conspirazorg challenged this interpretation as exactly &quot;what they want you to think.&quot; Plumb then acknowledged familiarity with conspiracy theories about Miter being &quot;a government contractor&quot; conducting &quot;psionic human testing&quot; to create &quot;super psychic soldiers.&quot;</p><p>This exchange established Plumb&#39;s typical hosting pattern: offering mainstream interpretations while demonstrating awareness of alternative theories, allowing guests to elaborate conspiratorial explanations.</p><h4 id="rectford-shillman-episode-november-2025" tabindex="-1">Rectford Shillman Episode (November 2025) <a class="header-anchor" href="#rectford-shillman-episode-november-2025" aria-label="Permalink to &quot;Rectford Shillman Episode (November 2025)&quot;">​</a></h4><p>Plumb hosted Commissioner <a href="./Rectford-Shillman">Rectford Shillman</a> for discussion of cryptocurrency investment risks. During this episode, Plumb expressed concern about &quot;the salami blockchain&quot; project&#39;s connection to <a href="./../subjects/G-BOY">G*BOY</a>.</p><p>Plumb made several notable assertions during this episode:</p><ul><li>Referred to G*BOY as &quot;awful&quot;</li><li>Stated &quot;of course&quot; G*BOY is a &quot;terrorist&quot;</li><li>Identified &quot;the main thing&quot; as <a href="./../organizations/The-Bloc">The Bloc</a></li><li>Described The Bloc as &quot;hacktivists&quot; and &quot;terrorists&quot;</li><li>Warned The Bloc was &quot;doing something with G*BOY on The blockchain very soon&quot;</li></ul><p>He also referenced a &quot;government trained&quot; eagle (presumably a visual element in the studio) that was trained &quot;to hate terrorists,&quot; which reacted with screaming to mentions of G*BOY.</p><h2 id="public-profile" tabindex="-1">Public Profile <a class="header-anchor" href="#public-profile" aria-label="Permalink to &quot;Public Profile&quot;">​</a></h2><p>Plumb&#39;s on-air persona combines satirical commentary with substantive concerns about cryptocurrency regulation and anti-government activism. His measured delivery style and deadpan reactions provide structural counterbalance to theatrical guest performances, creating a format that simultaneously mocks and engages with conspiracy theories and financial speculation.</p><p>His characterization of <a href="./../organizations/The-Bloc">The Bloc</a> as &quot;terrorists&quot; and warnings about their blockchain activities reflect either genuine concern about hacktivist organizations or satirical exaggeration of government and media narratives about activist groups.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Conspirazorg">Conspirazorg</a></li><li><a href="./Rectford-Shillman">Rectford Shillman</a></li><li><a href="./../organizations/SnarkCast">SnarkCast</a></li><li><a href="./../subjects/G-BOY">G*BOY</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../organizations/Market-Talk">Market Talk</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>SnarkCast episode</strong> — Featuring Conspirazorg (November 12, 2025) <ul><li>Satirical podcast discussing Miter Corporation conspiracy theories</li></ul></li><li><strong>SnarkCast episode</strong> — Featuring Rectford Shillman (November 26, 2025) <ul><li>Satirical podcast discussing cryptocurrency risks and G*BOY blockchain activities</li></ul></li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',33)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
